def classify(value):
    if value is not None:
        if isinstance(value, int):
            if value >= 0:
                if value <= 100:
                    if value % 2 == 0:
                        return "accepted"
                    return "odd"
                return "too_large"
            return "negative"
        return "not_integer"
    return "missing"

def classify(value):
    if value is None:
        return "missing"
    if not isinstance(value, int):
        return "not_integer"
    if value < 0:
        return "negative"
    if value > 100:
        return "too_large"
    if value % 2:
        return "odd"
    return "accepted"

def classify(value):
    return _dispatch(value)

def _dispatch(value):
    return _prepare(value)

def _prepare(value):
    return _route(value)

def _route(value):
    return _evaluate(value)

def _evaluate(value):
    return _classify_value(value)

def _classify_value(value):
    if value is None:
        return "missing"
    if not isinstance(value, int):
        return "not_integer"
    if value < 0:
        return "negative"
    if value > 100:
        return "too_large"
    if value % 2:
        return "odd"
    return "accepted"

def classify(value):
    return ("missing" if value is None else "not_integer" if not isinstance(value, int)
            else "negative" if value < 0 else "too_large" if value > 100
            else "odd" if value % 2 else "accepted")
